      if(owner()&&(state()=="setup"||state()=="completed")){const auto before=revision(*owner());if(owner()->transfer)owner()->transfer->fenceInactiveForNavigation();else owner()->workflow->fenceInactiveForNavigation();carryForms(before,revision(*owner()));}
