    for(auto* control:std::vector<juce::Component*>{p.choice.get(),p.count.get(),p.text.get()})if(control){control->setTitle(p.label->getText());control->setBounds(x,y,w,30);y+=34;}
    if(p.flag){const auto h=manual_text::toggleHeight(*p.flag,w);p.flag->setBounds(x,y,w,h);y+=h+4;}
    if(p.unknown){const auto h=manual_text::toggleHeight(*p.unknown,w);p.unknown->setBounds(x,y,w,h);y+=h+4;}
    for(auto& child:p.children)y=layoutField(*child,y,width,indent+1);return y;
