std::string AdvancedRecipeTaskView::learnerText()const{
    if(!owner())return "Open a verified task to begin.";std::ostringstream out;const auto safeInstructions=instructions();for(const auto& line:f(safeInstructions,"text").array())out<<line.string()<<"\n\n";
    auto stable=learnerView();for(const auto* name:{"state","stage","written_pass","bar","register"})stable.object().erase(name);out<<"Printed facts and your retained choices\n";describe(out,stable);
    if(transferTask())if(auto guidance=transferTask()->priorityGuidance())out<<"Retry priority: "<<*guidance<<'\n';out<<"\nYour reports are manual declarations. No source clock, fixed tempo, audio scheduler, observed performance or credit is supplied.";return out.str();
}
std::string AdvancedRecipeTaskView::historyText()const{
    const auto retained=retainedHistory();A recent;for(const auto& e:retained.array())if(f(e,"key").string()==key_)recent.push_back(e);const V all(recent);std::ostringstream out;out<<retained.array().size()<<" full manual events retained across "<<owners_.size()<<" owned tasks. Current task summaries below; full typed reports remain in the retained owner history.\n";
    const auto start=all.array().size()>12?all.array().size()-12:0;
    for(std::size_t n=start;n<all.array().size();++n){const auto& event=all.array()[n];out<<"Event "<<n+1<<": "<<human(valueText(f(event,"before")))<<" → "<<human(valueText(f(event,"after")))<<". ";const auto& report=f(event,"reported");
      if(report.isString())out<<"Your diagnosis: "<<preview(report.string());else if(report.isBool())out<<"Your manual acknowledgement: "<<valueText(report);else if(report.isObject()){
        bool details=false;for(const auto* name:{"diagnosis","notes","pitch_name","named_pitch","attack_count","sing_count","response_speed"})if(const auto* p=report.find(name)){if(p->isString()&&p->string().empty())continue;out<<human(name)<<": "<<preview(valueText(*p))<<". ";details=true;}if(!details)out<<report.object().size()<<" typed fields retained.";
      }out<<'\n';
    }auto text=out.str();if(text.size()>3500){std::size_t end=3500;while((static_cast<unsigned char>(text[end])&0xc0)==0x80)--end;text.resize(end);text+="\n… Full typed details remain retained.";}return text;
}
