    heading_.setText("Manual source exercises",juce::dontSendNotification);phase_.setText(ju(phaseText()),juce::dontSendNotification);const auto learnerTextNow=learnerText();if(learnerTextNow!=cachedLearnerText_){cachedLearnerText_=learnerTextNow;manual_text::setReadOnlyText(learner_,ju(cachedLearnerText_));++learnerTextLayouts_;}const auto historyTextNow=historyText();if(historyTextNow!=cachedHistoryText_){cachedHistoryText_=historyTextNow;manual_text::setReadOnlyText(history_,ju(cachedHistoryText_));++historyTextLayouts_;}status_.setText(ju(message_),juce::dontSendNotification);
